const input = $json;
const stages = Array.isArray(input.stages) ? input.stages : (input.stages ? JSON.parse(input.stages) : []);
const stageByCode = new Map(stages.map(stage => [stage.stage_code, stage]));
const targetCode = input.stage_code;
const targetSeq = Number(input.seq);
const stageId = Number(input.stage_id || input.requested_stage_id || 0);
const requestedOverride = String(input.override_token || '').trim();
const overrideAccepted = requestedOverride.startsWith('OVR:' + stageId + ':');
const satisfied = stage => stage && ['complete', 'skipped'].includes(stage.status);
const required = [];
if (!input.stage_id) {
  return [{ json: { ...input, allowed: false, blocked_by: [], reason: 'Stage not found.', override_token: null } }];
}
if (['complete', 'skipped'].includes(input.status)) {
  return [{ json: { ...input, allowed: false, blocked_by: [], reason: input.stage_name + ' is already ' + input.status + '.', override_token: null } }];
}
if (targetSeq > 2) required.push('MOVEOUT');
const ruleMap = {
  PAINT: ['REPAIRS'],
  FLOORING: ['PAINT'],
  DEEP_CLEAN: ['REPAIRS', 'PAINT', 'FLOORING'],
  QA_PHOTOS: ['DEEP_CLEAN'],
  RELIST: ['QA_PHOTOS']
};
for (const code of ruleMap[targetCode] || []) {
  if (!required.includes(code)) required.push(code);
}
const missing = required
  .map(code => stageByCode.get(code))
  .filter(stage => !satisfied(stage))
  .sort((a, b) => Number(a.seq) - Number(b.seq));
if (missing.length === 0 || overrideAccepted) {
  return [{ json: {
    ...input,
    allowed: true,
    override: overrideAccepted,
    blocked_by: missing.map(stage => ({ stage_code: stage.stage_code, stage_name: stage.stage_name, status: stage.status })),
    reason: overrideAccepted ? 'Manager override accepted.' : 'Sequence guard passed.',
    completed_via: overrideAccepted ? 'override' : (input.requested_completed_via || (input.actor_type === 'vendor' ? 'vendor_reply' : 'manual'))
  } }];
}
const first = missing[0];
let reason = first.stage_name + ' is still open on ' + input.unit_label + '.';
if (targetCode === 'DEEP_CLEAN' && first.stage_code === 'REPAIRS') {
  reason = 'Repairs still open on ' + input.unit_label + '. Cleaning before repairs means cleaning twice.';
}
return [{ json: {
  ...input,
  allowed: false,
  override: false,
  blocked_by: missing.map(stage => ({ stage_code: stage.stage_code, stage_name: stage.stage_name, status: stage.status })),
  reason,
  override_token: 'OVR:' + stageId + ':' + Date.now()
} }];

const q=typeof $json.outbound_queue==='string'?JSON.parse($json.outbound_queue):$json.outbound_queue;
const next=typeof $json.next_stage==='string'?JSON.parse($json.next_stage):$json.next_stage;
if(!q) return [{json:{...$json,has_queue:false}}];
const openai_request={
  model:'gpt-5.6-luna',
  input:[
    {role:'system',content:[{type:'input_text',text:'Rewrite the factual vendor handoff to be concise and professional. Preserve every fact. Add no promises, dates, prices, or instructions. Return only JSON.'}]},
    {role:'user',content:[{type:'input_text',text:q.deterministic_text}]}
  ],
  text:{format:{type:'json_schema',name:'vendor_draft',strict:true,schema:{type:'object',additionalProperties:false,required:['draft'],properties:{draft:{type:'string',minLength:1,maxLength:1000}}}}}
};
return [{json:{...$json,has_queue:true,queue:q,next_stage:next,openai_request}}];

const source=$('Stage Call Shared Completion Handler Build Safe Vendor Draft Request').first().json; let draft=source.queue.deterministic_text; let fallback=true;
try { const raw=$json||{}; const text=raw.output_text||(raw.output||[]).flatMap(o=>o.content||[]).find(c=>c.type==='output_text')?.text; const parsed=typeof text==='string'?JSON.parse(text):null; if(parsed&&typeof parsed.draft==='string'&&parsed.draft.trim()){draft=parsed.draft.trim();fallback=false;} } catch(e) {}
return [{json:{...source,draft_text:draft,draft_fallback_used:fallback}}];

const qid=Number($json.queue_id||0); const chat=String($json.manager_chat_id||'');
return [{json:{...$json,should_send_manager_approval:qid>0&&chat&&!chat.includes('missing'),manager_approval_text:'Stage completed. Next vendor handoff is ready.

'+String($json.draft_text||'')+'

Choose a delivery channel. Nothing has been sent yet.'}}];
